void Dashboard(){if(!Can("projects.read")){content.Controls.Add(new Label{Text="배포 사용자 화면 · 왼쪽의 허용된 업무 메뉴를 선택하세요.\n표시되는 메뉴가 없으면 관리자에게 사용 권한을 요청하세요.",AutoSize=true,Font=new Font(Font.FontFamily,14)});return;}var p=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(0)};content.Controls.Add(p);decimal contract=J.Rows(state,"projects").Sum(x=>J.Num(x,"contract")),paid=J.Rows(state,"projects").Sum(x=>J.Num(x,"paid")),expense=J.Rows(state,"projects").Sum(x=>J.Num(x,"actualCost"));var hero=new BrandBanner();p.Controls.Add(hero);p.SetFlowBreak(hero,true);var welcome=new Label{Text="나무의 결을 따라, 공간의 품격을 높이다.\n"+DateTime.Today.ToString("yyyy.MM.dd")+"  ·  "+J.Text(user,"name")+"님의 업무 현황",Width=950,Height=55,Font=new Font(Font.FontFamily,13),ForeColor=Style.Muted};p.Controls.Add(welcome);p.SetFlowBreak(welcome,true);foreach(Panel card in new[]{Style.Metric("진행 중인 현장",J.Rows(state,"projects").Count(x=>J.Text(x,"status")!="완료")+"건","등록 현장 기준"),Style.Metric("총 계약 금액",J.Money(contract),"현장 계약 금액 합계"),Style.Metric("받을 금액",J.Money(contract-paid),"계약 금액 − 누적 수금"),Style.Metric("수금 후 잔액",J.Money(paid-expense),"누적 수금 − 기록 지출")})p.Controls.Add(card);var actions=new FlowLayoutPanel{Width=950,Height=68,Margin=new Padding(0,12,0,12)};actions.Controls.Add(Style.Button("새 견적 작성",(o,e)=>{ShowPage("quotes");EditRecord(null);}));actions.Controls.Add(Style.Button("새 현장 등록",(o,e)=>{ShowPage("projects");EditRecord(null);}));actions.Controls.Add(Style.Button("계단 3D 설계",(o,e)=>ShowPage("design")));actions.Controls.Add(Style.Button("시공 일정 확인",(o,e)=>ShowPage("tasks")));if(HasBusiness())actions.Controls.Add(Style.Button("사업 운영 · 문서",(o,e)=>ShowPage("business")));if(Can("reports.read"))actions.Controls.Add(Style.Button("통계 · 보고서",(o,e)=>ShowPage("reports")));p.Controls.Add(actions);p.SetFlowBreak(actions,true);var title=new Label{Text="다가오는 시공 일정",Width=950,Height=36,Font=new Font(Font.FontFamily,15,FontStyle.Bold)};p.Controls.Add(title);p.SetFlowBreak(title,true);int shown=0;foreach(D t in J.Rows(state,"tasks").OrderBy(x=>J.Text(x,"date"))){DateTime day;if(!DateTime.TryParse(J.Text(t,"date"),out day)||day.Date<DateTime.Today||J.Text(t,"status")=="완료")continue;var row=new Label{Text=day.ToString("MM.dd")+"   "+J.Text(t,"time")+"   "+J.Text(t,"name")+"   ·   "+RecordName("projects",J.Text(t,"project"))+"   ·   "+J.Text(t,"owner"),Width=950,Height=48,Padding=new Padding(14),BackColor=Color.White,Margin=new Padding(0,0,0,7)};p.Controls.Add(row);p.SetFlowBreak(row,true);if(++shown>=5)break;}if(shown==0){var empty=new Label{Text="예정된 일정이 없습니다. 시공 일정을 등록해 현장 준비를 시작하세요.",Width=950,Height=56,Padding=new Padding(14),BackColor=Color.White,ForeColor=Style.Muted};p.Controls.Add(empty);p.SetFlowBreak(empty,true);}p.Controls.Add(new Label{Text="OREUM MOK  /  CRAFTED WITH CARE   ·   목공과 전기 기술을 하나의 현장으로",Width=950,Height=50,ForeColor=Style.Muted,Padding=new Padding(0,20,0,0)});}
Field[] Fields(string k){if(k=="customers")return new[]{new Field("name","고객명"),new Field("phone","연락처"),new Field("address","주소"),new Field("businessNo","사업자등록번호 (해당 시)"),new Field("contact","담당자"),new Field("source","유입 경로","select","지인 소개,블로그,당근,검색,기타"),new Field("note","상담 메모","note")};if(k=="projects")return new[]{new Field("name","현장명"),new Field("customer","고객","customers"),new Field("address","시공 주소"),new Field("status","단계","select","상담,가견적,실측,견적,계약,발주,제작,시공,완료,보류"),new Field("start","시작일","date"),new Field("end","완료 예정일","date"),new Field("category","공종","select","목공·계단,간접조명,전기·조명,시설물보수,기타"),new Field("paymentTerms","계약금·중도금·잔금 조건","note"),new Field("taxMode","계약 합계의 과세 기준","select","미확정,포함,면세"),new Field("vatRate","VAT 세율 % (예시 10)","number"),new Field("costBasis","참고 손익 원가 기준","select","지출총액,확인공급가"),new Field("costNet","공급가 기준 실제 원가 (확인한 값)","number"),new Field("contract","계약 합계 (VAT 포함)","number"),new Field("paid","수금 누계","number"),new Field("actualCost","실제 지출 누계","number"),new Field("note","특이사항 · AS","note")};if(k=="materials")return new[]{new Field("name","자재명 / 규격"),new Field("category","분류","select","목재,난간,LED,전원장치,전선,철물,도장,기타"),new Field("unit","단위"),new Field("stock","현재 재고","number"),new Field("min","최소 재고","number"),new Field("cost","매입 공급단가","number"),new Field("supplier","공급처"),new Field("note","보관 위치 · 메모","note")};if(k=="orders")return new[]{new Field("name","발주명"),new Field("project","현장","projects"),new Field("material","자재","materials"),new Field("supplier","공급처"),new Field("qty","수량","number"),new Field("cost","공급단가","number"),new Field("date","납기","date"),new Field("status","상태","select","작성,발주완료,취소"),new Field("note","배송 메모","note")};return new[]{new Field("name","작업명"),new Field("project","현장","projects"),new Field("date","작업일","date"),new Field("time","시간 (HH:mm)"),new Field("owner","담당","select","목공 담당,전기 담당,공동,외주"),new Field("status","상태","select","예정,진행,완료,보류"),new Field("note","준비물 · 내용","note")};}
void EditRecord(D original){if(!Can(page+".write")){MessageBox.Show("조회 전용입니다. 관리자에게 편집 권한을 요청하세요.");return;}if(page=="quotes"){OpenWorkspace(new QuoteForm(b,J.Clone(state),original,WorkspaceCommit("quotes",original)));return;}string group=page;D r=original??J.Row("id",Guid.NewGuid().ToString());if(group=="projects"){if(!r.ContainsKey("vatRate"))r["vatRate"]=10;if(!r.ContainsKey("taxMode"))r["taxMode"]="미확정";if(!r.ContainsKey("costBasis"))r["costBasis"]="지출총액";}var safeCommit=WorkspaceCommit(group,original);var f=new EditForm(names[group],r,Fields(group),J.Clone(state),q=>{if(group=="projects"){DateTime a,c;if(DateTime.TryParse(J.Text(q,"start"),out a)&&DateTime.TryParse(J.Text(q,"end"),out c)&&c<a){MessageBox.Show("완료일은 시작일 이후여야 합니다.");return false;}}return safeCommit(q);});OpenWorkspace(f);}
bool Store(string group,D row){if(!Can(group+".write")){MessageBox.Show("관리자가 허용하지 않은 편집 작업입니다.");return false;}D n=J.Clone(state);var rows=J.Rows(n,group);int index=rows.FindIndex(x=>J.Text(x,"id")==J.Text(row,"id"));if(index<0)rows.Add(row);else rows[index]=row;n[group]=rows.ToArray();return Commit(n);}
void DeleteRecord(){if(!Can(page+".write")){MessageBox.Show("삭제 권한이 없습니다.");return;}D r=Selected();if(r==null)return;string id=J.Text(r,"id");bool used=(page=="customers"&&(J.Rows(state,"projects").Any(x=>J.Text(x,"customer")==id)||J.Rows(state,"quotes").Any(x=>J.Text(x,"customer")==id)))||(page=="projects"&&new[]{"orders","tasks","transactions","stockMoves","designs","siteChecks","paymentPlans","labor","defects","documents","taxRecords","lighting"}.Any(k=>J.Rows(state,k).Any(x=>J.Text(x,"project")==id)))||(page=="materials"&&new[]{"orders","stockMoves"}.Any(k=>J.Rows(state,k).Any(x=>J.Text(x,"material")==id)))||(page=="orders"&&J.Bool(r,"received"))||(page=="quotes"&&J.Rows(state,"projects").Any(x=>J.Text(x,"quote")==id));if(used){MessageBox.Show("연결된 이력이나 입고가 있어 삭제할 수 없습니다.");return;}if(MessageBox.Show("선택한 항목을 삭제할까요?","삭제",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;D n=J.Clone(state);n[page]=J.Rows(n,page).Where(x=>J.Text(x,"id")!=id).ToArray();Commit(n);}
void Receive(){if(!Can("orders.write")){MessageBox.Show("관리자가 허용하지 않은 작업입니다.");return;}D r=Selected();if(r==null||J.Bool(r,"received"))return;D n=J.Clone(state),o=J.Rows(n,"orders").First(x=>J.Text(x,"id")==J.Text(r,"id")),m=J.Rows(n,"materials").FirstOrDefault(x=>J.Text(x,"id")==J.Text(o,"material"));if(m==null||J.Num(o,"qty")<=0){MessageBox.Show("자재 연결과 수량을 확인하세요.");return;}if(MessageBox.Show("입고를 반영할까요?","입고",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;m["stock"]=J.Num(m,"stock")+J.Num(o,"qty");o["received"]=true;o["status"]="입고완료";Commit(n);}
void Stock(){if(!Can("stockMoves.write")){MessageBox.Show("관리자가 허용하지 않은 작업입니다.");return;}D m=Selected();if(m==null)return;D input=J.Row("qty",0,"project","","note","");using(var f=new EditForm("출고 · 현재 재고 "+J.Num(m,"stock")+" "+J.Text(m,"unit"),input,new[]{new Field("project","사용 현장","projects"),new Field("qty","출고 수량","number"),new Field("note","사용 메모","note")},state,q=>{if(J.Num(q,"qty")<=0||J.Num(q,"qty")>J.Num(m,"stock")||J.Text(q,"project")==""){MessageBox.Show("현장과 출고 수량을 확인하세요.");return false;}D n=J.Clone(state),target=J.Rows(n,"materials").First(x=>J.Text(x,"id")==J.Text(m,"id"));target["stock"]=J.Num(target,"stock")-J.Num(q,"qty");var moves=J.Rows(n,"stockMoves");moves.Add(J.Row("id",Guid.NewGuid().ToString(),"material",J.Text(m,"id"),"project",J.Text(q,"project"),"qty",J.Num(q,"qty"),"note",J.Text(q,"note"),"date",DateTime.Today.ToString("yyyy-MM-dd")));n["stockMoves"]=moves.ToArray();return Commit(n);}))f.ShowDialog(this);}
void Ledger(){if(!Can("transactions.read")){MessageBox.Show("입출금 조회 권한이 없습니다.");return;}D project=Selected();if(project==null)return;using(var form=new Form{Text="입출금 장부 · "+J.Text(project,"name"),Width=950,Height=600}){Style.Form(form);var g=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};foreach(string label in new[]{"거래일","구분","금액","수단","상태","내용"})g.Columns.Add(label,label);foreach(D row in J.Rows(state,"transactions").Where(t=>J.Text(t,"project")==J.Text(project,"id"))){int i=g.Rows.Add(J.Text(row,"date"),J.Text(row,"kind")=="receipt"?"수금":"지출",J.Money(J.Num(row,"amount")),J.Text(row,"method"),J.Text(row,"status","기록"),J.Text(row,"note"));g.Rows[i].Tag=row;}var bar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=58};var add=Style.Button("수금 / 지출 등록",(o,e)=>{AddTransaction(project);form.Close();});add.Enabled=Can("transactions.write")&&Can("projects.write");bar.Controls.Add(add);var cancel=Style.Button("선택 거래 입력 정정",(o,e)=>{D t=g.CurrentRow==null?null:g.CurrentRow.Tag as D;if(t==null)return;using(var dialog=new EditForm("입력 정정 · 원본 보존 / 실제 반환 아님",J.Row("reason",""),new[]{new Field("reason","정정 사유","note")},null,x=>{try{b.Call("cancelTransaction",J.Row("id",J.Text(t,"id"),"reason",J.Text(x,"reason"),"version",version));LoadState();ShowPage(page);return true;}catch(Exception ex){MessageBox.Show(ex.Message);return false;}}))if(dialog.ShowDialog(form)==DialogResult.OK)form.Close();});cancel.Enabled=Can("transactions.write")&&Can("projects.write");bar.Controls.Add(cancel);form.Controls.Add(g);form.Controls.Add(bar);form.ShowDialog(this);}}

void AddTransaction(D project){D input=J.Row("kind","receipt","date",DateTime.Today.ToString("yyyy-MM-dd"));using(var f=new EditForm("입출금 · "+J.Text(project,"name"),input,new[]{new Field("kind","receipt=수금 / expense=지출","select","receipt,expense"),new Field("date","거래일","date"),new Field("amount","금액 (VAT 포함)","number"),new Field("category","비용·수금 분류","select","계약금,중도금,잔금,자재비,인건비,외주비,운반비,출장비,장비비,기타"),new Field("method","결제 수단","select","계좌이체,현금,카드,기타"),new Field("reference","증빙 번호 / 보관 위치"),new Field("note","거래 내용","note")},state,q=>{if(J.Num(q,"amount")<=0){MessageBox.Show("양의 금액을 입력하세요.");return false;}D n=J.Clone(state),p=J.Rows(n,"projects").First(x=>J.Text(x,"id")==J.Text(project,"id"));string key=J.Text(q,"kind")=="receipt"?"paid":"actualCost";p[key]=J.Num(p,key)+J.Num(q,"amount");q["id"]=Guid.NewGuid().ToString();q["project"]=J.Text(project,"id");var rows=J.Rows(n,"transactions");rows.Add(q);n["transactions"]=rows.ToArray();return Commit(n);}))f.ShowDialog(this);}
void Inspection(){if(!Can("projects.write")){MessageBox.Show("관리자가 허용하지 않은 작업입니다.");return;}D p=Selected();if(p==null)return;D input=J.Clone(p);using(var f=new EditForm("시공 검수 · "+J.Text(p,"name"),input,new[]{new Field("woodCheck","발판·구조체·난간","select","미확인,확인,보수 필요"),new Field("electricCheck","기존 배선·전원·점검구","select","미확인,확인,보수 필요"),new Field("lightCheck","LED·센서·점등 시험","select","미확인,확인,보수 필요"),new Field("finishCheck","도장·미끄럼·모서리","select","미확인,확인,보수 필요"),new Field("inspectionMemo","고객 확인·AS 메모","note")},state,q=>{q["inspectedAt"]=DateTime.Today.ToString("yyyy-MM-dd");return Store("projects",q);}))f.ShowDialog(this);}
void ConvertQuote(){D q=Selected();if(q==null)return;try{bool refresh=J.Rows(state,"projects").Any(p=>J.Text(p,"quote")==J.Text(q,"id"));if(refresh&&MessageBox.Show("승인 견적을 연결 현장에 다시 반영할까요? 기존 수금·지출은 유지합니다.","견적 재반영",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;b.Call("convertQuote",J.Row("id",J.Text(q,"id"),"refresh",refresh,"version",version));LoadState();ShowPage("projects");}catch(Exception e){MessageBox.Show(e.Message);}}
void PrintQuote(){D q=Selected();if(q==null)return;try{D result=b.Call("quoteView",J.Row("id",J.Text(q,"id"),"export",true));string[] lines=((System.Collections.IEnumerable)result["lines"]).Cast<object>().Select(Convert.ToString).ToArray();PrintBusinessLines(lines,J.Text(q,"number","오름목 견적서"));}catch(Exception e){MessageBox.Show(e.Message);}}
void ExportCsv(){if(!Can("export")){MessageBox.Show("내보내기 권한이 없습니다.");return;}using(var d=new SaveFileDialog{Filter="CSV 파일|*.csv",FileName="오름목-"+page+".csv"})if(d.ShowDialog()==DialogResult.OK){var lines=new List<string>();Func<string,string> cell=x=>"\""+((x.Length>0&&"=+-@\t\r".Contains(x[0]))?"'":"")+x.Replace("\"","\"\"")+"\"";lines.Add(String.Join(",",grid.Columns.Cast<DataGridViewColumn>().Select(c=>cell(c.HeaderText))));foreach(DataGridViewRow r in grid.Rows)lines.Add(String.Join(",",r.Cells.Cast<DataGridViewCell>().Select(c=>cell(Convert.ToString(c.Value)))));File.WriteAllLines(d.FileName,lines,new UTF8Encoding(true));}}
void Reference(){var text=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=Color.White,Font=new Font(Font.FontFamily,12),Text="PDF 검토 기준 · 난간 참고단가\r\n\r\n미송 목재 170,000원/m · 오크 목재 200,000원/m · 기본 철재 230,000원/m\r\n2021년 공개자료 / VAT 포함 여부 미확인 / 오름목 원가·확정 단가가 아닙니다.\r\n\r\n목재 민자·투톤·로구로 / 기본 철재·목재 손스침·단조·유리 선택을 지원합니다.\r\n목재 제작 3~4일 · 철재 6~7일 · 조립식 약10일은 원문의 참고 기간입니다.\r\n\r\n원가와 판매단가를 분리하여 견적에 적용하세요. 경쟁사 5년·2년 보증을 자동 약속하지 않습니다.\r\n흐린 계단 가격표는 원본 가로80px로, 20배 확대 후에도 정확한 숫자를 확인할 수 없습니다.\r\n\r\n자세한 근거는 함께 설치된 PDF_REVIEW.md 및 PDF_IMAGE_FINDINGS.md에 기록했습니다."};content.Controls.Add(text);text.BringToFront();}
void Settings(){var p=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(0),AutoScroll=true};content.Controls.Add(p);p.SendToBack();if(Can("appearance"))p.Controls.Add(Style.Button("디자인 설정",(s,e)=>Appearance()));if(Can("admin"))p.Controls.Add(Style.Button("사용자 권한 관리",(s,e)=>ManageUsers()));p.Controls.Add(new Label{Text=J.Text(user,"name")+" / "+J.Text(user,"username")+" / "+J.Text(user,"role"),AutoSize=true,Margin=new Padding(12)});p.Controls.Add(Style.Button("전체 JSON 백업",(s,e)=>{using(var f=new SaveFileDialog{Filter="JSON|*.json",FileName="오름목-백업-"+DateTime.Today.ToString("yyyyMMdd")+".json"})if(f.ShowDialog()==DialogResult.OK){try{File.WriteAllText(f.FileName,J.S.Serialize(J.Obj(b.Call("backup")["state"])),Encoding.UTF8);}catch(Exception ex){MessageBox.Show(ex.Message,"백업 실패");}}}));if(Can("admin"))p.Controls.Add(Style.Button("JSON 복원",(s,e)=>{using(var f=new OpenFileDialog{Filter="JSON|*.json"})if(f.ShowDialog()==DialogResult.OK&&MessageBox.Show("현재 전체 업무 자료를 교체합니다. 백업 후 진행하세요.","복원",MessageBoxButtons.YesNo)==DialogResult.Yes){try{b.Call("restore",J.Row("state",J.Obj(J.S.DeserializeObject(File.ReadAllText(f.FileName,Encoding.UTF8))),"version",version,"confirm",true));LoadState();ShowPage("settings");}catch(Exception ex){MessageBox.Show(ex.Message);}}}));p.Controls.Add(Style.Button("Android 연결 안내",(s,e)=>{if(b.IsRemote){MessageBox.Show("현재 클라우드/서버 주소: "+b.RemoteUrl+"\r\n휴대폰도 같은 서버 주소와 해당 서버 계정으로 로그인하세요.\r\n클라우드 사용에는 이 PC를 계속 켤 필요가 없습니다.","모바일 연결");return;}D n=b.Call("network");string[] hosts=((IEnumerable)n["addresses"]).Cast<object>().Select(Convert.ToString).ToArray();MessageBox.Show("PC 앱을 켠 상태에서 같은 Wi-Fi의 Android 앱에 아래 주소를 입력하세요.\r\n\r\n"+String.Join("\r\n",hosts.Select(x=>"http://"+x+":48733"))+"\r\n\r\nUSB로 연결했다면 휴대폰 주소는 http://127.0.0.1:48733 입니다.\r\nPC에서 adb reverse tcp:48733 tcp:48733 설정이 필요합니다.\r\nWi-Fi는 위 PC 주소를 사용하세요.","모바일 앱 연결");}));if(J.Text(user,"role")=="admin")p.Controls.Add(Style.Button("배포 사용자 추가",(s,e)=>CreateUser()));p.Controls.Add(Style.Button("비밀번호 변경",(s,e)=>{using(var dialog=new Form{Text="비밀번호 변경",Width=430,Height=320}){Style.Form(dialog);var box=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(24),FlowDirection=FlowDirection.TopDown};dialog.Controls.Add(box);var oldPassword=new TextBox{Width=340,UseSystemPasswordChar=true};var newPassword=new TextBox{Width=340,UseSystemPasswordChar=true};var confirmPassword=new TextBox{Width=340,UseSystemPasswordChar=true};foreach(var pair in new[]{new object[]{"현재 비밀번호",oldPassword},new object[]{"새 비밀번호 (10자 이상)",newPassword},new object[]{"새 비밀번호 확인",confirmPassword}}){box.Controls.Add(new Label{Text=(string)pair[0],AutoSize=true});box.Controls.Add((Control)pair[1]);}box.Controls.Add(Style.Button("변경 후 다시 로그인",(a,c)=>{try{if(newPassword.Text!=confirmPassword.Text)throw new Exception("비밀번호 확인이 다릅니다.");b.Call("password",J.Row("currentPassword",oldPassword.Text,"password",newPassword.Text));LoginStore.Forget(b.IsRemote,true);MessageBox.Show("변경했습니다. 프로그램을 다시 실행해 로그인하세요.");dialog.Close();Close();}catch(Exception ex){MessageBox.Show(ex.Message);}}));dialog.ShowDialog(this);}}));p.Controls.Add(Style.Button("로그아웃 / 종료",(s,e)=>{try{b.Call("logout",J.Row("deviceToken",LoginStore.Token(b.IsRemote)));}catch{}try{LoginStore.Forget(b.IsRemote,true);}catch{}Close();}));p.Controls.Add(new Label{Text="자료는 기존 %LOCALAPPDATA%\\OreumMok 위치를 이어서 사용합니다.\r\n웹 버전은 종료하고 사용하세요. 네이티브 앱끼리는 저장 버전 충돌을 검사합니다.\r\nAndroid APK는 휴대폰에서 직접 설치해야 합니다.",Width=900,Height=130,Margin=new Padding(12)});}
void CreateUser(){using(var f=new CredentialForm("친구 계정 추가"))if(f.ShowDialog(this)==DialogResult.OK)try{b.Call("createUser",J.Row("username",f.Username,"name",f.Username,"password",f.Password,"role","staff"));MessageBox.Show("계정을 추가했습니다. 사용자 권한 관리에서 허용할 업무를 선택하세요.");}catch(Exception ex){MessageBox.Show(ex.Message);}}
}
class CredentialForm:Form {TextBox username=new TextBox(),password=new TextBox();public string Username{get{return username.Text;}}public string Password{get{return password.Text;}}public CredentialForm(string title){Style.Form(this);Text=title;Width=420;Height=260;var p=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(25),FlowDirection=FlowDirection.TopDown};Controls.Add(p);p.Controls.Add(new Label{Text="아이디 (영문·숫자 3~32자)",AutoSize=true});username.Width=330;p.Controls.Add(username);p.Controls.Add(new Label{Text="초기 비밀번호 (10자 이상)",AutoSize=true});password.Width=330;password.UseSystemPasswordChar=true;p.Controls.Add(password);p.Controls.Add(Style.Button("등록",(s,e)=>{DialogResult=DialogResult.OK;Close();}));}}
}
